INSERT INTO `blog_posts` (`id`, `title`, `content`, `excerpt`, `image`, `category_id`, `slug`, `is_featured`, `is_active`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES ('1', 'Nowe inwestycje w naszym mieście', '<p>W najbliższym czasie planowane są liczne inwestycje infrastrukturalne. Sprawdzamy, które miejsca zmienią się najbardziej i co oznacza to dla mieszkańców.</p>', 'W najbliższym czasie planowane są liczne inwestycje. 66600.pl będzie na bieżąco informować o wszystkich. Zapraszamy do śledzenia tego wątku 📌 ', 'post-nowe-inwestycje-w-miescie.avif', '1', 'nowe-inwestycje-w-naszym-miescie', '1', '1', '', '', '2026-08-11 14:44:26', '2026-08-12 00:04:22');
INSERT INTO `blog_posts` (`id`, `title`, `content`, `excerpt`, `image`, `category_id`, `slug`, `is_featured`, `is_active`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES ('2', 'Bezpieczeństwo na drogach', '<p>W Krośnie Odrzańskim trwają duże prace drogowe na drodze krajowej nr 29 (DK29) oraz budowa nowej obwodnicy miasta. Od 29 lipca 2026 roku wprowadzono kolejny etap remontu nawierzchni w ciągu DK29 (ul. Bohaterów Wojska Polskiego), co wiąże się z zamknięciem ważnego skrzyżowania i ruchem wahadłowym lub objazdami.Główne inwestycje i utrudnieniaRemont DK29: Prace prowadzi firma Strabag na odcinku ulicy Bohaterów Wojska Polskiego. Występują utrudnienia i ruch wahadłowy, a od końca lipca zamknięto ważne skrzyżowanie z wyznaczonym objazdem. Planowane zakończenie tego etapu prac przypada na 19 sierpnia 2026 roku.Budowa obwodnicy Krosna Odrzańskiego: Trwa wielka inwestycja w ciągu DK29 obejmująca budowę 11,4-kilometrowej trasy, nowych wiaduktów i mostu na Odrze. Ruch w rejonie inwestycji bywa kierowany na tymczasowe bypassy (m.in. w ciągu drogi powiatowej nr 1163F).Gdzie sprawdzić aktualny stan drogiKomunikaty policji znajdziesz na stronie Komenda Powiatowa Policji w Krośnie Odrzańskim.Bieżące informacje o utrudnieniach i ruchu wahadłowym publikuje NaviExpert Traffic.Oficjalne komunikaty o inwestycji udostępnia Generalna Dyrekcja Dróg Krajowych i Autostrad</p>', 'Zwracamy uwagę na trwające pracę drogowe w okolicy ulic Wojska Polskiego i Gubińskiej.', '6a7b9e70d5608.avif', '2', 'bezpieczenstwo-na-drogach', '1', '1', '', '', '2026-08-11 14:44:26', '2026-08-12 00:15:30');
INSERT INTO `blog_posts` (`id`, `title`, `content`, `excerpt`, `image`, `category_id`, `slug`, `is_featured`, `is_active`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES ('3', 'Parki i tereny rekreacyjne', '<p>Odwiedź nasze piękne parki i ciesz się aktywnym wypoczynkiem. Zebraliśmy propozycje spacerów i miejsc dobrych na rodzinny weekend.</p>', 'Odwiedź nasze piękne parki...', 'post-parki-i-tereny-rekreacyjne.avif', '3', 'parki-i-tereny-rekreacyjne', '1', '1', NULL, NULL, '2026-08-11 14:44:26', '2026-08-11 14:44:26');

